import numpy as np
# MECHANISM: Use a logarithmic function for preference scores to give more weight to very large remaining capacities.

def priority(item, bins):
    max_capacity = 150
    remaining = bins - item
    return np.log(1 + remaining / max_capacity)

import numpy as np
# MECHANISM: Use a different polynomial decay function for preference scores based on remaining capacity.

def priority(item, bins):
    return np.where(bins - item > 0, bins - item / (bins ** 0.5), 0)

