import numpy as np
# MECHANISM: Use a sigmoid function to balance between tight fit and spreading items over many bins.

def priority(item, bins):
    max_capacity = 150
    remaining = bins - item
    return 1 / (1 + np.exp(-(remaining / max_capacity - 0.5) * 10))

