import numpy as np
# MECHANISM: Use a piecewise function to balance between tight fit and spreading items over many bins.

def priority(item, bins):
    max_capacity = 150
    # Piecewise function to balance tight fit and spreading
    return np.piecewise(bins, [bins > item, bins <= item], [lambda x: x - item, lambda x: max_capacity - x])

import numpy as np
# MECHANISM: Use a piecewise function to balance between tight fit and spreading items over many bins, with a focus on spreading items.

def priority(item, bins):
    max_capacity = 150
    # Piecewise function to balance tight fit and spreading
    return np.piecewise(bins, [bins > item, bins <= item], [lambda x: (x - item) / max_capacity, lambda x: max_capacity / x])

import numpy as np

# MECHANISM: Use a modified exponential decay function to balance between tight fit and spreading items over many bins.

def priority(item, bins):
